  /**
   * Returns an array of unique userIds that are members of a document
   * either via group or direct membership.
   *
   * @param documentId
   * @param permission optional permission filter
   *
   * @returns userIds
   */
  static async membershipUserIds(
    documentId: string,
    permission?: DocumentPermission
  ) {
    const document = await this.scope("withAllMemberships").findOne({
      where: { id: documentId },
      include: [
        {
          association: "memberships",
          required: false,
          ...(permission ? { where: { permission } } : {}),
          separate: true,
        },
        {
          association: "groupMemberships",
          required: false,
          ...(permission ? { where: { permission } } : {}),
          separate: true,
        },
      ],
    });
    if (!document) {
      return [];
    }

    const groupMemberships = document.groupMemberships
      .map((gm) => gm.group.groupUsers)
      .flat();
    const membershipUserIds = [
      ...groupMemberships,
      ...document.memberships,
    ].map((membership) => membership.userId);
    return uniq(membershipUserIds);
  }

  /**
   * Returns an array of unique document IDs that the user is a member of,
   * either via direct membership or through a group membership.
   *
   * The result is cached briefly, mirroring `User.collectionIds`, as it is
   * resolved on every search request.
   *
   * @param userId The user ID to find document memberships for.
   * @param options Set `skipCache` to always read through to the database.
   * @returns A promise resolving to an array of document IDs.
   */
  static async membershipDocumentIds(
    userId: string,
    options: { skipCache?: boolean } = {}
  ): Promise<string[]> {
    const fetchDocumentIds = async () => {
      const [memberships, groupMemberships] = await Promise.all([
        UserMembership.findAll({
          attributes: ["documentId"],
          where: {
            userId,
            documentId: {
              [Op.ne]: null,
            },
          },
        }),
        GroupMembership.findAll({
          attributes: ["documentId"],
          where: {
            documentId: {
              [Op.ne]: null,
            },
          },
          include: [
            {
              model: Group,
              as: "group",
              attributes: [],
              required: true,
              include: [
                {
                  model: GroupUser,
                  as: "groupUsers",
                  attributes: [],
                  required: true,
                  where: {
                    userId,
                  },
                },
              ],
            },
          ],
        }),
      ]);

      return uniq(
        [...memberships, ...groupMemberships]
          .map((membership) => membership.documentId)
          .filter((id): id is string => !isNil(id))
      );
    };

    if (options.skipCache) {
      return fetchDocumentIds();
    }

    return (
      (await CacheHelper.getDataOrSet<string[]>(
        RedisPrefixHelper.getUserMembershipDocumentIdsKey(userId),
        fetchDocumentIds,
        Document.membershipDocumentIdsCacheTTL
      )) ?? []
    );
  }

  /**
   * Invalidates the cached result of `membershipDocumentIds` so a permission
   * change takes effect immediately rather than at the end of the cache TTL.
   *
   * @param userIds The users whose document memberships changed.
   */
  static async invalidateMembershipDocumentIds(userIds: string[]) {
    await Promise.all(
      uniq(userIds).map((userId) =>
        CacheHelper.removeData(
          RedisPrefixHelper.getUserMembershipDocumentIdsKey(userId)
        )
      )
    );
  }

  static withMembershipScope(
    userId: string,
    options?: FindOptions<Document> & { includeDrafts?: boolean }
  ) {
    return this.scope([
      options?.includeDrafts ? "withDrafts" : "defaultScope",
      "withoutState",
      {
        method: ["withViews", userId],
      },
      {
        method: ["withMembership", userId, options?.paranoid],
      },
    ]);
  }

  /**
   * Overrides the standard findByPk behavior to allow also querying by urlId
   * and loading memberships for a user passed in by `userId`
   *
   * @param id uuid or urlId
   * @param options FindOptions
   * @returns A promise resolving to a document instance or null
   */
  static async findByPk(
    id: Identifier,
    options?: NonNullFindOptions<Document> & AdditionalFindOptions
  ): Promise<Document>;
  static async findByPk(
    id: Identifier,
    options?: FindOptions<Document> & AdditionalFindOptions
  ): Promise<Document | null>;
  static async findByPk(
    id: Identifier,
    options: (NonNullFindOptions<Document> | FindOptions<Document>) &
      AdditionalFindOptions = {}
  ): Promise<Document | null> {
    if (typeof id !== "string") {
      return null;
    }

    const {
      includeViews = true,
      includeState = false,
      includeContent = true,
      userId,
      ...rest
    } = options;

    let contentScope = includeState ? "withState" : "withoutState";
    if (!includeContent) {
      contentScope = "withoutContent";
    }

    // allow default preloading of collection membership if `userId` is passed in find options
    // almost every endpoint needs the collection membership to determine policy permissions.
    const scope = this.scope([
      "withDrafts",
      contentScope,
      ...((includeViews
        ? [
            {
              method: ["withViews", userId],
            },
          ]
        : []) as ScopeOptions[]),
      {
        method: ["withMembership", userId, rest.paranoid],
      },
    ]);

    if (isUUID(id)) {
      const document = await scope.findOne({
        ...rest,
        where: {
          id,
        },
        rejectOnEmpty: false,
      });

      if (!document && rest.rejectOnEmpty) {
        throw rest.rejectOnEmpty instanceof Error
          ? rest.rejectOnEmpty
          : new EmptyResultError(`Document doesn't exist with id: ${id}`);
      }

      return document;
    }

    const match = id.match(UrlHelper.SLUG_URL_REGEX);
    if (match) {
      const document = await scope.findOne({
        ...rest,
        where: {
          urlId: match[1],
        },
        rejectOnEmpty: false,
      });

      if (!document && rest.rejectOnEmpty) {
        throw rest.rejectOnEmpty instanceof Error
          ? rest.rejectOnEmpty
          : new EmptyResultError(`Document doesn't exist with id: ${id}`);
      }

      return document;
    }

    return null;
  }

  /**
   * Find many documents by their id, supports filtering by user memberships when `userId`
   * is specified in the options.
   *
   * @param ids An array of document ids
   * @param options FindOptions
   * @returns A promise resolving to the list of documents
   */
  static async findByIds(
    ids: string[],
    options: Omit<FindOptions<Document>, "where"> &
      Omit<AdditionalFindOptions, "rejectOnEmpty"> = {}
  ): Promise<Document[]> {
    const { userId, includeViews = true, includeState, ...rest } = options;

    const user = userId ? await User.findByPk(userId) : null;
    const documents = await this.scope([
      "withDrafts",
      includeState ? "withState" : "withoutState",
      ...((includeViews
        ? [
            {
              method: ["withViews", userId],
            },
          ]
        : []) as ScopeOptions[]),
      {
        method: ["withMembership", userId],
      },
    ]).findAll({
      where: {
        ...(user && { teamId: user.teamId }),
        id: ids,
      },
      ...rest,
    });

    if (!userId) {
      return documents;
    }

    return documents.filter((doc) => {
      if (doc.memberships.length > 0 || doc.groupMemberships.length > 0) {
        return true;
      }

      // A document without a collection is either an unfiled draft or lives in
      // a collection the user cannot see – access is limited to the creator.
      if (!doc.collection) {
        return doc.createdById === userId;
      }

      return (
        (!doc.collection.isPrivate && !user?.isGuest) ||
        doc.collection.memberships.length > 0 ||
        doc.collection.groupMemberships.length > 0
      );
    });
  }

  // instance methods

  /**
   * Whether this document is considered active or not. A document is active if
   * it has not been archived or deleted.
   *
   * @returns boolean
   */
  get isActive(): boolean {
    return !this.archivedAt && !this.deletedAt;
  }

  /**
   * Sets the value of the given display preference.
   *
   * @param preference The document preference to set
   * @param value Sets the preference value
   * @returns The current document preferences
   */
  public setPreference = <T extends keyof DocumentPreferences>(
    preference: T,
    value: DocumentPreferences[T]
  ) => {
    this.preferences = {
      ...this.preferences,
      [preference]: value,
    };

    return this.preferences;
  };

  /**
   * Returns the value of the given display preference.
   *
   * @param preference The document preference to retrieve
   * @returns The preference value if set, else the default value
   */
  public getPreference = <T extends DocumentPreference>(preference: T) =>
    this.preferences?.[preference] ?? DocumentPreferenceDefaults[preference];

  /**
   * Convenience method that returns whether this document is a draft.
   *
   * @returns boolean
   */
  get isDraft(): boolean {
    return !this.publishedAt;
  }

  /**
   * Returns the title of the document or a default if the document is untitled.
   *
   * @returns boolean
   */
  get titleWithDefault(): string {
    return this.title || "Untitled";
  }

  /**
   * Whether this document was imported during a trial period.
   *
   * @returns boolean
   */
  get isTrialImport() {
    return !!(this.importId && this.sourceMetadata?.trial);
  }

  /**
   * Revert the state of the document to match the passed revision.
   *
   * @param revision The revision to revert to.
   */
  restoreFromRevision = async (revision: Revision) => {
    if (revision.documentId !== this.id) {
      throw new Error("Revision does not belong to this document");
    }

    this.content = revision.content;
    this.text = await DocumentHelper.toMarkdown(revision, {
      includeTitle: false,
    });
    this.title = revision.title;
    this.icon = revision.icon;
    this.color = revision.color;
  };

  /**
   * Get a list of users that have collaborated on this document
   *
   * @param options FindOptions
   * @returns A promise that resolve to a list of users
   */
  collaborators = async (options?: FindOptions<User>): Promise<User[]> =>
    await User.findAll({
      ...options,
      where: Object.assign({}, options?.where, { id: this.collaboratorIds }),
    });

  /**
   * Find all of the child documents for this document
   *
   * @param where Omit<WhereOptions<Document>, "parentDocumentId">
   * @param options FindOptions
   * @returns A promise that resolve to a list of documents
   */
  findChildDocuments = async (
    where?: Omit<WhereOptions<Document>, "parentDocumentId">,
    options?: FindOptions<Document>
  ): Promise<Document[]> =>
    await (this.constructor as typeof Document).findAll({
      where: {
        parentDocumentId: this.id,
        ...where,
      },
      ...options,
    });

  /**
   * Calculate all of the document ids that are children of this document by
   * recursively iterating through parentDocumentId references in the most efficient way.
   *
   * @param where query options to further filter the documents
   * @param options FindOptions
   * @returns A promise that resolves to a list of document ids
   */
  findAllChildDocumentIds = async (
    where?: Omit<WhereOptions<Document>, "parentDocumentId">,
    options?: FindOptions<Document>
  ): Promise<string[]> => {
    const model = this.constructor as typeof Document;
    const queryGenerator = this.sequelize!.getQueryInterface()
      .queryGenerator as QueryGeneratorWithWhere;

    const paranoid = options?.paranoid ?? true;
    const whereConditions = queryGenerator.getWhereConditions(
      { ...(paranoid ? { deletedAt: null } : {}), ...where },
      "documents",
      model
    );
    const anchorFilter = whereConditions ? `AND (${whereConditions})` : "";
    const recursiveFilter = whereConditions ? `WHERE (${whereConditions})` : "";

    // A single recursive CTE walks the entire subtree in one round-trip rather
    // than issuing one query per level of nesting (N+1). Rows are ordered by
    // depth to ensure breadth-first result ordering. UNION ALL is safe as the
    // tree is acyclic, so each descendant id is reached exactly once.
    const rows = await this.sequelize!.query<{ id: string }>(
      `
      WITH RECURSIVE children AS (
        SELECT documents.id, 1 AS depth
        FROM documents
        WHERE documents."parentDocumentId" = :parentDocumentId
          ${anchorFilter}
        UNION ALL
        SELECT documents.id, children.depth + 1
        FROM documents
        INNER JOIN children ON documents."parentDocumentId" = children.id
        ${recursiveFilter}
      )
      SELECT id FROM children ORDER BY depth
      `,
      {
        replacements: { parentDocumentId: this.id },
        transaction: options?.transaction,
        type: QueryTypes.SELECT,
      }
    );

    return rows.map((row) => row.id);
  };

  publish = async (
    ctx: APIContext,
    {
      index = 0,
      collectionId,
      silent = false,
      event = true,
      data,
    }: {
      index?: number;
      collectionId: string | null | undefined;
      silent?: boolean;
      event?: boolean;
      data?: Record<string, unknown>;
    }
  ): Promise<this> => {
    const { user } = ctx.state.auth;
    const { transaction } = ctx.state;

    this.lastModifiedById = user.id;
    this.updatedBy = user;

    // If the document is already published then calling publish should act like
    // a regular save
    if (this.publishedAt) {
      if (event) {
        return this.saveWithCtx(ctx, { silent }, { name: "publish", data });
      } else {
        return this.save({ silent, transaction });
      }
    }

    if (!this.collectionId) {
      this.collectionId = collectionId;
    }

    if (this.collectionId) {
      const collection = await Collection.findByPk(this.collectionId, {
        includeDocumentStructure: true,
        transaction,
        lock: Transaction.LOCK.NO_KEY_UPDATE,
      });

      if (collection) {
        await collection.addDocumentToStructure(this, index, { transaction });
        if (this.collection) {
          this.collection.documentStructure = collection.documentStructure;
        }
      }
    }

    // Copy the group and user memberships from the parent document, if any
    if (this.parentDocumentId) {
      await GroupMembership.copy(
        {
          documentId: this.parentDocumentId,
        },
        this,
        { transaction }
      );
      await UserMembership.copy(
        {
          documentId: this.parentDocumentId,
        },
        this,
        { transaction }
      );
    }

    this.publishedAt = new Date();

    if (event) {
      return this.saveWithCtx(ctx, { silent }, { name: "publish", data });
    } else {
      return this.save({ silent, transaction });
    }
  };

  isCollectionDeleted = async () => {
    if (this.deletedAt || this.archivedAt) {
      if (this.collectionId) {
        const collection =
          this.collection ??
          (await Collection.findByPk(this.collectionId, {
            attributes: ["deletedAt"],
            paranoid: false,
          }));

        return !!collection?.deletedAt;
      }
    }
    return false;
  };

  /**
   * Unpublishes a published document, converting it back to a draft.
   *
   * @param ctx the API context.
   * @param options.detach whether to detach the document from the containing collection.
   * @returns updated document.
   * @throws if the document has child documents.
   */
  unpublishWithCtx = async (ctx: APIContext, options: { detach: boolean }) => {
    // If the document is already a draft then calling unpublish should act like save
    if (!this.publishedAt) {
      return this.save();
    }

    const { user } = ctx.state.auth;
    const { transaction } = ctx.state;

    const childDocumentIds = await this.findAllChildDocumentIds(
      { archivedAt: { [Op.eq]: null } },
      { transaction }
    );
    if (childDocumentIds.length > 0) {
      throw InvalidRequestError(
        "Cannot unpublish document with child documents"
      );
    }

    const collection = this.collectionId
      ? await Collection.findByPk(this.collectionId, {
          includeDocumentStructure: true,
          transaction,
          lock: transaction?.LOCK.NO_KEY_UPDATE,
        })
      : undefined;

    if (collection) {
      await collection.removeDocumentInStructure(this, { transaction });
      if (this.collection) {
        this.collection.documentStructure = collection.documentStructure;
      }
    }

    // unpublishing a document converts the ownership to yourself, so that it
    // will appear in your drafts rather than the original creators
    this.createdById = user.id;
    this.lastModifiedById = user.id;
    this.createdBy = user;
    this.updatedBy = user;
    this.publishedAt = null;

    if (options.detach) {
      this.collectionId = null;
    }

    return this.saveWithCtx(ctx, undefined, { name: "unpublish" });
  };

  // Moves a document from being visible to the team within a collection
  // to the archived area, where it can be subsequently restored.
  archiveWithCtx = async (ctx: APIContext) => {
    const { transaction } = ctx.state;
    const collection = this.collectionId
      ? await Collection.findByPk(this.collectionId, {
          includeDocumentStructure: true,
          transaction,
          lock: transaction?.LOCK.NO_KEY_UPDATE,
        })
      : undefined;

    if (collection) {
      await collection.removeDocumentInStructure(this, { transaction });
      if (this.collection) {
        this.collection.documentStructure = collection.documentStructure;
      }
    }

    await this.archiveWithChildren(ctx);
    return this;
  };

  // Restore an archived document back to being visible to the team
  restoreTo = async (
    ctx: APIContext,
    { collectionId }: { collectionId: string }
  ) => {
    const { transaction } = ctx.state;
    const collection = collectionId
      ? await Collection.findByPk(collectionId, {
          includeDocumentStructure: true,
          transaction,
          lock: transaction?.LOCK.NO_KEY_UPDATE,
        })
      : undefined;

    // check to see if the documents parent hasn't been archived also
    // If it has then restore the document to the collection root.
    if (this.parentDocumentId) {
      const parent = await (this.constructor as typeof Document).findOne({
        where: {
          id: this.parentDocumentId,
        },
        transaction,
      });
      if (parent?.isDraft || !parent?.isActive) {
        this.parentDocumentId = null;
      }
    }

    if (this.publishedAt && collection?.isActive) {
      await collection.addDocumentToStructure(this, undefined, {
        includeArchived: true,
        transaction,
      });
    }

    if (this.deletedAt) {
      await this.restore({ transaction });
      this.collectionId = collectionId;
      await this.saveWithCtx(ctx, undefined, { name: "restore" });
    }

    if (this.archivedAt) {
      await this.restoreArchivedWithChildren(ctx, { collectionId });
    }

    if (this.collection && collection) {
      // updating the document structure in memory just in case it's later accessed somewhere
      this.collection.documentStructure = collection.documentStructure;
    }
    return this;
  };

  // Delete a document, archived or otherwise.
  destroyWithCtx = async (
    ctx: APIContext,
    eventOpts?: EventOverrideOptions
  ): Promise<void> => {
    const { user } = ctx.state.auth;
    const { transaction } = ctx.state;
    let deleted = false;

    if (this.collectionId) {
      const collection = await Collection.findByPk(this.collectionId, {
        includeDocumentStructure: true,
        transaction,
        lock: transaction?.LOCK.NO_KEY_UPDATE,
        paranoid: false,
      });

      if (!this.archivedAt || (this.archivedAt && collection?.archivedAt)) {
        await collection?.deleteDocument(this, user, { transaction });
        deleted = true;
      }
    }

    if (!deleted) {
      await this.destroy({ transaction });
    }

    this.lastModifiedById = user.id;
    this.updatedBy = user;
    await this.saveWithCtx(ctx, undefined, { name: "delete", ...eventOpts });
  };

  getTimestamp = () => Math.round(new Date(this.updatedAt).getTime() / 1000);

  getSummary = () => {
    if (this.summary) {
      return this.summary;
    }

    const plainText = DocumentHelper.toPlainText(this);
    const lines = compact(plainText.split("\n"));
    const notEmpty = lines.length >= 1;

    if (this.version) {
      return notEmpty ? lines[0] : "";
    }

    return notEmpty ? lines[1] : "";
  };

  /**
   * Returns a JSON representation of the document suitable for use in the
   * collection documentStructure.
   *
   * @param options Optional transaction to use for the query
   * @returns Promise resolving to a NavigationNode
   */
  toNavigationNode = async (
    options?: FindOptions<Document> & { includeArchived?: boolean }
  ): Promise<NavigationNode> => {
    // Checking if the record is new is a performance optimization – new docs cannot have children
    const childDocuments = this.isNewRecord
      ? []
      : await (this.constructor as typeof Document).unscoped().findAll({
          where: options?.includeArchived
            ? {
                teamId: this.teamId,
                parentDocumentId: this.id,
                publishedAt: {
                  [Op.ne]: null,
                },
              }
            : {
                teamId: this.teamId,
                parentDocumentId: this.id,
                publishedAt: {
                  [Op.ne]: null,
                },
                archivedAt: {
                  [Op.is]: null,
                },
              },
          transaction: options?.transaction,
        });

    const children = await Promise.all(
      childDocuments.map((child) => child.toNavigationNode(options))
    );

    return {
      id: this.id,
      title: this.title,
      url: this.url,
      icon: isNil(this.icon) ? undefined : this.icon,
      color: isNil(this.color) ? undefined : this.color,
      children,
    };
  };

  private restoreArchivedWithChildren = async (
    ctx: APIContext,
    { collectionId }: { collectionId: string }
  ) => {
    const { user } = ctx.state.auth;
    const { transaction } = ctx.state;

    const restoreChildren = async (parentDocumentId: string) => {
      const childDocuments = await (
        this.constructor as typeof Document
      ).findAll({
        where: {
          parentDocumentId,
        },
        transaction,
      });
      for (const child of childDocuments) {
        await restoreChildren(child.id);
        child.archivedAt = null;
        child.lastModifiedById = user.id;
        child.updatedBy = user;
        child.collectionId = collectionId;
        await child.save({ transaction });
      }
    };

    await restoreChildren(this.id);
    this.archivedAt = null;
    this.lastModifiedById = user.id;
    this.updatedBy = user;
    this.collectionId = collectionId;
    return this.saveWithCtx(ctx, undefined, { name: "unarchive" });
  };

  private archiveWithChildren = async (ctx: APIContext) => {
    const { user } = ctx.state.auth;
    const { transaction } = ctx.state;
    const archivedAt = new Date();

    // Helper to archive all child documents for a document
    const archiveChildren = async (parentDocumentId: string) => {
      const childDocuments = await (
        this.constructor as typeof Document
      ).findAll({
        where: {
          parentDocumentId,
        },
        transaction,
      });
      for (const child of childDocuments) {
        await archiveChildren(child.id);
        child.archivedAt = archivedAt;
        child.lastModifiedById = user.id;
        child.updatedBy = user;
        await child.save({ transaction });
      }
    };

    await archiveChildren(this.id);
    this.archivedAt = archivedAt;
    this.lastModifiedById = user.id;
    this.updatedBy = user;
    return this.saveWithCtx(ctx, undefined, { name: "archive" });
  };
}

