    const { user } = ctx.state.auth;
    const { transaction } = ctx.state;
    let deleted = false;

    if (this.collectionId) {
      const collection = await Collection.findByPk(this.collectionId, {
        includeDocumentStructure: true,
        transaction,
        lock: transaction?.LOCK.NO_KEY_UPDATE,
        paranoid: false,
