  /**
   * Returns an array of unique userIds that are members of a document
   * either via group or direct membership.
   *
   * @param documentId
   * @param permission optional permission filter
   *
   * @returns userIds
   */
  static async membershipUserIds(
    documentId: string,
    permission?: DocumentPermission
  ) {
    const document = await this.scope("withAllMemberships").findOne({
      where: { id: documentId },
      include: [
        {
          association: "memberships",
          required: false,
          ...(permission ? { where: { permission } } : {}),
          separate: true,
        },
        {
          association: "groupMemberships",
          required: false,
          ...(permission ? { where: { permission } } : {}),
          separate: true,
        },
      ],
    });
    if (!document) {
      return [];
    }

    const groupMemberships = document.groupMemberships
      .map((gm) => gm.group.groupUsers)
      .flat();
    const membershipUserIds = [
      ...groupMemberships,
      ...document.memberships,
    ].map((membership) => membership.userId);
    return uniq(membershipUserIds);
  }

  /**
   * Returns an array of unique document IDs that the user is a member of,
   * either via direct membership or through a group membership.
   *
   * The result is cached briefly, mirroring `User.collectionIds`, as it is
   * resolved on every search request.
   *
   * @param userId The user ID to find document memberships for.
   * @param options Set `skipCache` to always read through to the database.
   * @returns A promise resolving to an array of document IDs.
   */
  static async membershipDocumentIds(
    userId: string,
    options: { skipCache?: boolean } = {}
  ): Promise<string[]> {
    const fetchDocumentIds = async () => {
      const [memberships, groupMemberships] = await Promise.all([
        UserMembership.findAll({
          attributes: ["documentId"],
          where: {
            userId,
            documentId: {
              [Op.ne]: null,
            },
          },
        }),
        GroupMembership.findAll({
          attributes: ["documentId"],
          where: {
            documentId: {
              [Op.ne]: null,
            },
          },
          include: [
            {
              model: Group,
              as: "group",
              attributes: [],
              required: true,
              include: [
                {
                  model: GroupUser,
                  as: "groupUsers",
                  attributes: [],
                  required: true,
                  where: {
                    userId,
                  },
                },
              ],
            },
          ],
        }),
      ]);

      return uniq(
        [...memberships, ...groupMemberships]
          .map((membership) => membership.documentId)
          .filter((id): id is string => !isNil(id))
      );
    };

    if (options.skipCache) {
      return fetchDocumentIds();
    }

    return (
      (await CacheHelper.getDataOrSet<string[]>(
        RedisPrefixHelper.getUserMembershipDocumentIdsKey(userId),
        fetchDocumentIds,
        Document.membershipDocumentIdsCacheTTL
      )) ?? []
    );
  }

  /**
   * Invalidates the cached result of `membershipDocumentIds` so a permission
   * change takes effect immediately rather than at the end of the cache TTL.
   *
   * @param userIds The users whose document memberships changed.
   */
  static async invalidateMembershipDocumentIds(userIds: string[]) {
    await Promise.all(
      uniq(userIds).map((userId) =>
        CacheHelper.removeData(
          RedisPrefixHelper.getUserMembershipDocumentIdsKey(userId)
        )
      )
    );
  }

  static withMembershipScope(
    userId: string,
    options?: FindOptions<Document> & { includeDrafts?: boolean }
  ) {
    return this.scope([
      options?.includeDrafts ? "withDrafts" : "defaultScope",
      "withoutState",
      {
        method: ["withViews", userId],
      },
      {
        method: ["withMembership", userId, options?.paranoid],
      },
    ]);
  }

  /**
   * Overrides the standard findByPk behavior to allow also querying by urlId
   * and loading memberships for a user passed in by `userId`
   *
   * @param id uuid or urlId
   * @param options FindOptions
   * @returns A promise resolving to a document instance or null
   */
  static async findByPk(
    id: Identifier,
    options?: NonNullFindOptions<Document> & AdditionalFindOptions
  ): Promise<Document>;
  static async findByPk(
    id: Identifier,
    options?: FindOptions<Document> & AdditionalFindOptions
  ): Promise<Document | null>;
  static async findByPk(
    id: Identifier,
    options: (NonNullFindOptions<Document> | FindOptions<Document>) &
      AdditionalFindOptions = {}
  ): Promise<Document | null> {
    if (typeof id !== "string") {
      return null;
    }

    const {
      includeViews = true,
      includeState = false,
      includeContent = true,
      userId,
      ...rest
    } = options;

    let contentScope = includeState ? "withState" : "withoutState";
    if (!includeContent) {
      contentScope = "withoutContent";
    }

    // allow default preloading of collection membership if `userId` is passed in find options
    // almost every endpoint needs the collection membership to determine policy permissions.
    const scope = this.scope([
      "withDrafts",
      contentScope,
      ...((includeViews
        ? [
            {
              method: ["withViews", userId],
            },
          ]
        : []) as ScopeOptions[]),
      {
        method: ["withMembership", userId, rest.paranoid],
      },
    ]);

    if (isUUID(id)) {
      const document = await scope.findOne({
        ...rest,
        where: {
          id,
        },
        rejectOnEmpty: false,
      });

      if (!document && rest.rejectOnEmpty) {
        throw rest.rejectOnEmpty instanceof Error
          ? rest.rejectOnEmpty
          : new EmptyResultError(`Document doesn't exist with id: ${id}`);
      }

      return document;
    }

    const match = id.match(UrlHelper.SLUG_URL_REGEX);
    if (match) {
      const document = await scope.findOne({
        ...rest,
        where: {
          urlId: match[1],
        },
        rejectOnEmpty: false,
      });

      if (!document && rest.rejectOnEmpty) {
        throw rest.rejectOnEmpty instanceof Error
          ? rest.rejectOnEmpty
          : new EmptyResultError(`Document doesn't exist with id: ${id}`);
      }

      return document;
    }

    return null;
  }

  /**
   * Find many documents by their id, supports filtering by user memberships when `userId`
   * is specified in the options.
   *
   * @param ids An array of document ids
   * @param options FindOptions
   * @returns A promise resolving to the list of documents
   */
  static async findByIds(
    ids: string[],
    options: Omit<FindOptions<Document>, "where"> &
      Omit<AdditionalFindOptions, "rejectOnEmpty"> = {}
  ): Promise<Document[]> {
    const { userId, includeViews = true, includeState, ...rest } = options;

    const user = userId ? await User.findByPk(userId) : null;
    const documents = await this.scope([
      "withDrafts",
      includeState ? "withState" : "withoutState",
      ...((includeViews
        ? [
            {
              method: ["withViews", userId],
            },
          ]
        : []) as ScopeOptions[]),
      {
        method: ["withMembership", userId],
      },
    ]).findAll({
      where: {
        ...(user && { teamId: user.teamId }),
        id: ids,
      },
      ...rest,
    });

    if (!userId) {
      return documents;
    }

    return documents.filter((doc) => {
      if (doc.memberships.length > 0 || doc.groupMemberships.length > 0) {
        return true;
      }

      // A document without a collection is either an unfiled draft or lives in
      // a collection the user cannot see – access is limited to the creator.
      if (!doc.collection) {
        return doc.createdById === userId;
      }

      return (
        (!doc.collection.isPrivate && !user?.isGuest) ||
        doc.collection.memberships.length > 0 ||
        doc.collection.groupMemberships.length > 0
      );
    });
  }

  // instance methods

  /**
   * Whether this document is considered active or not. A document is active if
   * it has not been archived or deleted.
   *
   * @returns boolean
   */
  get isActive(): boolean {
    return !this.archivedAt && !this.deletedAt;
  }

  /**
   * Sets the value of the given display preference.
   *
   * @param preference The document preference to set
   * @param value Sets the preference value
   * @returns The current document preferences
   */
  public setPreference = <T extends keyof DocumentPreferences>(
    preference: T,
    value: DocumentPreferences[T]
  ) => {
    this.preferences = {
      ...this.preferences,
      [preference]: value,
    };

    return this.preferences;
  };

  /**
   * Returns the value of the given display preference.
   *
   * @param preference The document preference to retrieve
   * @returns The preference value if set, else the default value
   */
  public getPreference = <T extends DocumentPreference>(preference: T) =>
    this.preferences?.[preference] ?? DocumentPreferenceDefaults[preference];

  /**
   * Convenience method that returns whether this document is a draft.
   *
   * @returns boolean
   */
  get isDraft(): boolean {
    return !this.publishedAt;
  }

  /**
   * Returns the title of the document or a default if the document is untitled.
   *
   * @returns boolean
